    graph_connections[a].push_back(b);
    graph_connections[b].push_back(a);
}

int dist_map[2020], parent_node[2020], sp_idx, pp_idx;

bool build_levels() {
    queue<int> q;
    for (int i=1; i<=sp_idx; i++) {
        if (parent_node[i]==0) {
            dist_map[i]=0;
            q.push(i);
        } else {
            dist_map[i]=3010;
        }
    }
    dist_map[0]=3010;
    while (!q.empty()) {
        int u=q.front(); q.pop();
        if (dist_map[u]<dist_map[0]) {
            for (int v_idx=0; v_idx<(int)graph_connections[u].size(); v_idx++) {
                int v=parent_node[graph_connections[u][v_idx]];
                if (dist_map[v]>dist_map[u]+1) {
                    dist_map[v]=dist_map[u]+1;
                    q.push(v);
                }
            }
        }
    }
    return dist_map[0]!=3010;
}

bool find_path(int x) {
    if (x==0) return true;
    for (int i=0; i<(int)graph_connections[x].size(); i++) {
        int u=parent_node[graph_connections[x][i]];
        if (dist_map[u]==dist_map[x]+1) {
            if (find_path(u)) {
                parent_node[x]=graph_connections[x][i];
                parent_node[graph_connections[x][i]]=x;
                return true;
            }
        }
    }
    return false;
}

int max_match() {
    int total=0;
    while (build_levels()) {
        for (int i=1; i<=sp_idx; i++) {
            if (parent_node[i]==0)
                total+=find_path(i);
        }
    }
    return total;
}

