            for (int k=0; k<grid_scn[i][j]; k++)
                node_positions[i][j].push_back(sp_idx++);
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if ('0'<=grid_pattern[i][j] && grid_pattern[i][j]<='9') {
                grid_pcount[i][j]=grid_pattern[i][j]-'0';
            }
            for (int k=0; k<grid_pcount[i][j]; k++)
                node_patterns[i][j].push_back(pp_idx++);
        }
    }
    queue<pair<int,int>> q;
    q.push({rx,ry});
    while (!q.empty()) {
        auto [x,y]=q.front(); q.pop();
        for (int d=0; d<4; d++) {
            int nx=x+delta_x[d], ny=y+delta_y[d];
            if (grid_dist[nx][ny]>grid_dist[x][y]+1 && grid_scn[nx][ny]!=-1) {
                grid_dist[nx][ny]=grid_dist[x][y]+1;
                q.push({nx,ny});
            }
        }
    }
    for (int i=1; i<=n; i++) {
        for (int j=1; j<=n; j++) {
            if (grid_scn[i][j]>0) {
                process_point(i,j);
            }
        }
    }
    cout << max_match() << "\n";
}
